```turtle
@prefix fis: <http://example.org/onto/securities#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
    a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology"@en ;
    rdfs:comment "An ontology formalizing securities, derivatives, debt, equity, and related financial structures as described in the source corpus."@en .

#################################################################
#    Object Properties
#################################################################

fis:hasIssuer
    a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Issuer ;
    owl:inverseOf fis:isIssuerOf ;
    rdfs:label "has issuer"@en .

fis:isIssuerOf
    a owl:ObjectProperty ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:label "is issuer of"@en .

fis:hasUnderlying
    a owl:ObjectProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:Underlying ;
    owl:inverseOf fis:isUnderlyingOf ;
    rdfs:label "has underlying"@en .

fis:isUnderlyingOf
    a owl:ObjectProperty ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:Derivative ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:label "is underlying of"@en .

fis:hasTradingVenue
    a owl:ObjectProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:TradingVenue ;
    owl:inverseOf fis:isTradingVenueOf ;
    rdfs:label "has trading venue"@en .

fis:isTradingVenueOf
    a owl:ObjectProperty ;
    rdfs:domain fis:TradingVenue ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasTradingVenue ;
    rdfs:label "is trading venue of"@en .

fis:hasCommonStock
    a owl:ObjectProperty ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range fis:CommonStock ;
    owl:inverseOf fis:isCommonStockOf ;
    rdfs:label "has common stock"@en .

fis:isCommonStockOf
    a owl:ObjectProperty ;
    rdfs:domain fis:CommonStock ;
    rdfs:range fis:ConvertibleBond ;
    owl:inverseOf fis:hasCommonStock ;
    rdfs:label "is common stock of"@en .

fis:hasMortgage
    a owl:ObjectProperty ;
    rdfs:domain fis:MortgageBackedSecurity ;
    rdfs:range fis:Mortgage ;
    owl:inverseOf fis:isMortgageOf ;
    rdfs:label "has mortgage"@en .

fis:isMortgageOf
    a owl:ObjectProperty ;
    rdfs:domain fis:Mortgage ;
    rdfs:range fis:MortgageBackedSecurity ;
    owl:inverseOf fis:hasMortgage ;
    rdfs:label "is mortgage of"@en .

fis:hasCallOption
    a owl:ObjectProperty ;
    rdfs:domain fis:CallableBond ;
    rdfs:range fis:CallOption ;
    owl:inverseOf fis:isCallOptionOf ;
    rdfs:label "has call option"@en .

fis:isCallOptionOf
    a owl:ObjectProperty ;
    rdfs:domain fis:CallOption ;
    rdfs:range fis:CallableBond ;
    owl:inverseOf fis:hasCallOption ;
    rdfs:label "is call option of"@en .

fis:hasPutOption
    a owl:ObjectProperty ;
    rdfs:domain fis:PutableBond ;
    rdfs:range fis:PutOption ;
    owl:inverseOf fis:isPutOptionOf ;
    rdfs:label "has put option"@en .

fis:isPutOptionOf
    a owl:ObjectProperty ;
    rdfs:domain fis:PutOption ;
    rdfs:range fis:PutableBond ;
    owl:inverseOf fis:hasPutOption ;
    rdfs:label "is put option of"@en .

fis:hasSecurity
    a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Security ;
    owl:inverseOf fis:isSecurityOf ;
    rdfs:label "has security"@en .

fis:isSecurityOf
    a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:InvestmentFund ;
    owl:inverseOf fis:hasSecurity ;
    rdfs:label "is security of"@en .

#################################################################
#    Data Properties
#################################################################

fis:hasMaturityDate
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:date ;
    rdfs:label "has maturity date"@en .

fis:hasParValue
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has par value"@en .

fis:hasCouponRate
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has coupon rate"@en .

fis:hasStrikePrice
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal ;
    rdfs:label "has strike price"@en .

fis:hasStandardization
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean ;
    rdfs:label "has standardization"@en .

#################################################################
#    Classes: Top-Level Taxonomy
#################################################################

fis:FinancialInstrument
    a owl:Class ;
    rdfs:label "Financial Instrument"@en ;
    rdfs:comment "A monetary contract between parties that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity."@en .

fis:Security
    a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Security"@en ;
    rdfs:comment "A tradable financial asset representing a claim on an issuer. Note conflict: in US law and broader usage, securities include derivatives, debt, and equities; in other jurisdictions and IAS accounting standards, securities specifically exclude derivatives or non-tradable instruments."@en .

fis:Derivative
    a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument, fis:Underlying ;
    rdfs:label "Derivative"@en ;
    rdfs:comment "A financial contract whose value depends on the value of one or more underlying reference assets, rates, indices, or events."@en .

fis:Underlying
    a owl:Class ;
    rdfs:label "Underlying"@en ;
    rdfs:comment "An asset, index, interest rate, currency, commodity, or event referenced by a derivative."@en .

fis:Issuer
    a owl:Class ;
    rdfs:label "Issuer"@en ;
    rdfs:comment "The legal entity obligated on a security or financial instrument."@en .

fis:TradingVenue
    a owl:Class ;
    rdfs:label "Trading Venue"@en ;
    rdfs:comment "The facility or environment in which financial instruments are traded."@en .

fis:Mortgage
    a owl:Class ;
    rdfs:subClassOf fis:Underlying ;
    rdfs:label "Mortgage"@en .

#################################################################
#    Classes: Trading Venues & Issuers
#################################################################

fis:Exchange
    a owl:Class ;
    rdfs:subClassOf fis:TradingVenue ;
    rdfs:label "Exchange"@en .

fis:OverTheCounterMarket
    a owl:Class ;
    rdfs:subClassOf fis:TradingVenue ;
    rdfs:label "Over-The-Counter Market"@en .

fis:Corporation
    a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Corporation"@en .

fis:SovereignGovernment
    a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Sovereign Government"@en .

fis:LocalGovernment
    a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Local Government"@en .

fis:SupranationalOrganization
    a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Supranational Organization"@en .

#################################################################
#    Classes: Securities Taxonomy
#################################################################

fis:DebtSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Debt Security"@en ;
    rdfs:comment "A negotiable financial instrument serving as evidence of a promise by the issuer to make payment of principal and interest to the holder on specified future dates."@en .

fis:EquitySecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security, fis:Underlying ;
    rdfs:label "Equity Security"@en ;
    rdfs:comment "A negotiable financial instrument representing an ownership interest in the issuing entity, conferring a residual claim on assets after creditor claims are satisfied."@en .

fis:HybridSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security"@en ;
    rdfs:comment "A security combining characteristics of both debt and equity securities."@en .

fis:InvestmentFund
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Investment Fund"@en ;
    rdfs:comment "An investment vehicle that pools capital from multiple investors to hold a portfolio of securities."@en .

#################################################################
#    Classes: Equity Securities
#################################################################

fis:Stock
    a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Stock"@en .

fis:CommonStock
    a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "Common Stock"@en ;
    rdfs:comment "Corporate equity ownership conferring voting rights and a residual claim on earnings and liquidation proceeds."@en .

fis:PreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
    rdfs:label "Preferred Stock"@en ;
    rdfs:comment "A class of capital stock that has preference over common stock in dividend payments and liquidation proceeds, typically without standard voting rights."@en .

fis:CumulativePreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Cumulative Preferred Stock"@en .

fis:NoncumulativePreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Noncumulative Preferred Stock"@en .

fis:ConvertiblePreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Convertible Preferred Stock"@en .

fis:DepositaryReceipt
    a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Depositary Receipt"@en .

#################################################################
#    Classes: Debt Securities & Bonds
#################################################################

fis:Bond
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Bond"@en ;
    rdfs:comment "A long-term debt instrument under which the borrower promises to repay principal at maturity and usually make periodic interest payments."@en .

fis:CorporateBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasIssuer ;
              owl:someValuesFrom fis:Corporation ]
        )
    ] ;
    rdfs:label "Corporate Bond"@en .

fis:GovernmentBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasIssuer ;
              owl:someValuesFrom fis:SovereignGovernment ]
        )
    ] ;
    rdfs:label "Government Bond"@en .

fis:MunicipalBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasIssuer ;
              owl:someValuesFrom fis:LocalGovernment ]
        )
    ] ;
    rdfs:label "Municipal Bond"@en .

fis:SupranationalBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasIssuer ;
              owl:someValuesFrom fis:SupranationalOrganization ]
        )
    ] ;
    rdfs:label "Supranational Bond"@en .

fis:ConvertibleBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasCommonStock ;
              owl:someValuesFrom fis:CommonStock ]
        )
    ] ;
    rdfs:label "Convertible Bond"@en .

fis:CallableBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasCallOption ;
              owl:someValuesFrom fis:CallOption ]
        )
    ] ;
    rdfs:label "Callable Bond"@en .

fis:PutableBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasPutOption ;
              owl:someValuesFrom fis:PutOption ]
        )
    ] ;
    rdfs:label "Putable Bond"@en .

fis:ZeroCouponBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasCouponRate ;
              owl:hasValue 0.0 ]
        )
    ] ;
    rdfs:label "Zero-Coupon Bond"@en .

fis:FixedRateBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Fixed Rate Bond"@en .

fis:FloatingRateNote
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Floating Rate Note"@en .

fis:PerpetualBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Perpetual Bond"@en .

fis:InflationIndexedBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Inflation-Indexed Bond"@en .

fis:CoveredBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Covered Bond"@en .

fis:AssetBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Asset-Backed Security"@en ;
    rdfs:comment "A debt security whose value and cash flows are derived from and backed by a specified pool of underlying assets."@en .

fis:MortgageBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:AssetBackedSecurity
            [ a owl:Restriction ;
              owl:onProperty fis:hasMortgage ;
              owl:someValuesFrom fis:Mortgage ]
        )
    ] ;
    rdfs:label "Mortgage-Backed Security"@en .

fis:ResidentialMortgageBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:MortgageBackedSecurity
            [ a owl:Restriction ;
              owl:onProperty fis:hasMortgage ;
              owl:someValuesFrom fis:ResidentialMortgage ]
        )
    ] ;
    rdfs:label "Residential Mortgage-Backed Security"@en .

fis:CommercialMortgageBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:MortgageBackedSecurity
            [ a owl:Restriction ;
              owl:onProperty fis:hasMortgage ;
              owl:someValuesFrom fis:CommercialMortgage ]
        )
    ] ;
    rdfs:label "Commercial Mortgage-Backed Security"@en .

fis:CollateralizedMortgageObligation
    a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation"@en .

fis:CollateralizedDebtObligation
    a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Collateralized Debt Obligation"@en .

fis:ResidentialMortgage
    a owl:Class ;
    rdfs:subClassOf fis:Mortgage ;
    rdfs:label "Residential Mortgage"@en .

fis:CommercialMortgage
    a owl:Class ;
    rdfs:subClassOf fis:Mortgage ;
    rdfs:label "Commercial Mortgage"@en .

fis:Debenture
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Debenture"@en ;
    rdfs:comment "An unsecured debt security with a long maturity, typically at least ten years."@en .

fis:MoneyMarketInstrument
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Money Market Instrument"@en ;
    rdfs:comment "Short-term debt securities with original maturities of one year or less, highly liquid."@en .

fis:CommercialPaper
    a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Commercial Paper"@en ;
    rdfs:comment "An unsecured short-term promissory note with a maturity of not more than 270 days."@en .

fis:CertificateOfDeposit
    a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Certificate of Deposit"@en .

fis:TreasuryBill
    a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Treasury Bill"@en .

#################################################################
#    Classes: Other Hybrid Securities
#################################################################

fis:EquityWarrant
    a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "Equity Warrant"@en ;
    rdfs:comment "An option issued by a company that gives the holder the right to purchase shares directly from the company at a specified price."@en .

#################################################################
#    Classes: Investment Funds
#################################################################

fis:MutualFund
    a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Mutual Fund"@en ;
    rdfs:comment "An open-end pooled investment vehicle purchased or redeemed at net asset value."@en .

fis:ExchangeTradedFund
    a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:InvestmentFund
            [ a owl:Restriction ;
              owl:onProperty fis:hasTradingVenue ;
              owl:someValuesFrom fis:Exchange ]
        )
    ] ;
    rdfs:label "Exchange-Traded Fund"@en .

#################################################################
#    Classes: Derivatives Taxonomy
#################################################################

fis:Forward
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [ a owl:Restriction ;
              owl:onProperty fis:hasTradingVenue ;
              owl:someValuesFrom fis:OverTheCounterMarket ]
            [ a owl:Restriction ;
              owl:onProperty fis:hasStandardization ;
              owl:hasValue false ]
        )
    ] ;
    rdfs:label "Forward"@en ;
    rdfs:comment "A customized, non-standardized bilateral contract traded over the counter to buy or sell an asset at a predetermined price on a future date."@en .

fis:Future
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [ a owl:Restriction ;
              owl:onProperty fis:hasTradingVenue ;
              owl:someValuesFrom fis:Exchange ]
            [ a owl:Restriction ;
              owl:onProperty fis:hasStandardization ;
              owl:hasValue true ]
        )
    ] ;
    rdfs:label "Future"@en ;
    rdfs:comment "A standardized contract traded on an exchange and cleared through a clearing house to buy or sell an asset at a predetermined price on a future delivery date."@en .

fis:Option
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Option"@en ;
    rdfs:comment "A derivative contract conveying to the holder the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date."@en .

fis:CallOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Call Option"@en ;
    rdfs:comment "An option giving the holder the right to buy the underlying asset."@en .

fis:PutOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Put Option"@en ;
    rdfs:comment "An option giving the holder the right to sell the underlying asset."@en .

fis:Swap
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Swap"@en ;
    rdfs:comment "A derivative agreement between counterparties to exchange streams of cash flows based on specified reference instruments or rates."@en .

fis:InterestRateSwap
    a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Interest Rate Swap"@en .

fis:CurrencySwap
    a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Currency Swap"@en .

fis:CreditDefaultSwap
    a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Credit Default Swap"@en ;
    rdfs:comment "A credit swap agreement providing protection against default or credit events on an underlying reference debt obligation."@en .

fis:EquityDerivative
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [ a owl:Restriction ;
              owl:onProperty fis:hasUnderlying ;
              owl:someValuesFrom fis:EquitySecurity ]
        )
    ] ;
    rdfs:label "Equity Derivative"@en .

#################################################################
#    Disjointness Axioms
#################################################################

[] a owl:AllDisjointClasses ;
   owl:members (
       fis:Forward
       fis:Future
       fis:Option
       fis:Swap
   ) .

[] a owl:AllDisjointClasses ;
   owl:members (
       fis:CallOption
       fis:PutOption
   ) .

[] a owl:AllDisjointClasses ;
   owl:members (
       fis:CorporateBond
       fis:GovernmentBond
       fis:MunicipalBond
       fis:SupranationalBond
   ) .

[] a owl:AllDisjointClasses ;
   owl:members (
       fis:CumulativePreferredStock
       fis:NoncumulativePreferredStock
   ) .

[] a owl:AllDisjointClasses ;
   owl:members (
       fis:Corporation
       fis:LocalGovernment
       fis:SovereignGovernment
       fis:SupranationalOrganization
   ) .

[] a owl:AllDisjointClasses ;
   owl:members (
       fis:Exchange
       fis:OverTheCounterMarket
   ) .

[] a owl:AllDisjointClasses ;
   owl:members (
       fis:ResidentialMortgage
       fis:CommercialMortgage
   ) .
```
